CREATE TABLE "attendance_records" ("id" UUID NOT NULL, "employee_id" UUID NOT NULL, "attendance_date" DATE NOT NULL, "attendance_type" VARCHAR(40) NOT NULL, "work_hours" DECIMAL(18,4), "overtime_hours" DECIMAL(18,4), "remark" VARCHAR(1000), "attachment" JSONB NOT NULL DEFAULT '[]', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, "created_by" UUID NOT NULL, "updated_by" UUID NOT NULL, "deleted_at" TIMESTAMP(3), "deleted_by" UUID, CONSTRAINT "attendance_records_pkey" PRIMARY KEY ("id"));
CREATE TABLE "performance_records" ("id" UUID NOT NULL, "employee_id" UUID NOT NULL, "period_start" DATE NOT NULL, "period_end" DATE NOT NULL, "score" DECIMAL(8,4), "grade" VARCHAR(30), "reward_amount" DECIMAL(18,4) NOT NULL DEFAULT 0, "comment" VARCHAR(1000), "attachment" JSONB NOT NULL DEFAULT '[]', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, "created_by" UUID NOT NULL, "updated_by" UUID NOT NULL, "deleted_at" TIMESTAMP(3), "deleted_by" UUID, CONSTRAINT "performance_records_pkey" PRIMARY KEY ("id"));
CREATE TABLE "payroll_ledgers" ("id" UUID NOT NULL, "ledger_no" VARCHAR(100) NOT NULL, "employee_id" UUID NOT NULL, "period_start" DATE NOT NULL, "period_end" DATE NOT NULL, "currency" VARCHAR(10) NOT NULL, "base_salary" DECIMAL(18,4) NOT NULL DEFAULT 0, "production_source_amount" DECIMAL(18,4) NOT NULL DEFAULT 0, "overtime_amount" DECIMAL(18,4) NOT NULL DEFAULT 0, "attendance_deduction" DECIMAL(18,4) NOT NULL DEFAULT 0, "performance_amount" DECIMAL(18,4) NOT NULL DEFAULT 0, "allowance_amount" DECIMAL(18,4) NOT NULL DEFAULT 0, "social_insurance" DECIMAL(18,4) NOT NULL DEFAULT 0, "individual_tax" DECIMAL(18,4) NOT NULL DEFAULT 0, "other_adjustment" DECIMAL(18,4) NOT NULL DEFAULT 0, "source_snapshot" JSONB NOT NULL, "status" VARCHAR(30) NOT NULL DEFAULT 'draft', "attachment" JSONB NOT NULL DEFAULT '[]', "remark" VARCHAR(1000), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, "created_by" UUID NOT NULL, "updated_by" UUID NOT NULL, "deleted_at" TIMESTAMP(3), "deleted_by" UUID, CONSTRAINT "payroll_ledgers_pkey" PRIMARY KEY ("id"));
CREATE TABLE "payroll_adjustments" ("id" UUID NOT NULL, "adjustment_no" VARCHAR(100) NOT NULL, "ledger_id" UUID NOT NULL, "employee_id" UUID NOT NULL, "adjustment_type" VARCHAR(40) NOT NULL, "effect" VARCHAR(20) NOT NULL, "amount" DECIMAL(18,4) NOT NULL, "reason" VARCHAR(1000) NOT NULL, "status" VARCHAR(30) NOT NULL DEFAULT 'draft', "attachment" JSONB NOT NULL DEFAULT '[]', "remark" VARCHAR(1000), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, "created_by" UUID NOT NULL, "updated_by" UUID NOT NULL, "deleted_at" TIMESTAMP(3), "deleted_by" UUID, CONSTRAINT "payroll_adjustments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "salary_payments" ("id" UUID NOT NULL, "payment_no" VARCHAR(100) NOT NULL, "payment_date" DATE NOT NULL, "amount" DECIMAL(18,4) NOT NULL, "currency" VARCHAR(10) NOT NULL, "payment_method" VARCHAR(50) NOT NULL, "bank_reference" VARCHAR(200), "status" VARCHAR(30) NOT NULL DEFAULT 'draft', "attachment" JSONB NOT NULL DEFAULT '[]', "remark" VARCHAR(1000), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, "created_by" UUID NOT NULL, "updated_by" UUID NOT NULL, "deleted_at" TIMESTAMP(3), "deleted_by" UUID, CONSTRAINT "salary_payments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "salary_payment_allocations" ("id" UUID NOT NULL, "payment_id" UUID NOT NULL, "ledger_id" UUID NOT NULL, "employee_id" UUID NOT NULL, "amount" DECIMAL(18,4) NOT NULL, "currency" VARCHAR(10) NOT NULL, "status" VARCHAR(30) NOT NULL DEFAULT 'active', "remark" VARCHAR(1000), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, "created_by" UUID NOT NULL, "updated_by" UUID NOT NULL, "deleted_at" TIMESTAMP(3), "deleted_by" UUID, CONSTRAINT "salary_payment_allocations_pkey" PRIMARY KEY ("id"));
